import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; END=pd.Timestamp('2027-09-22'); P={}
for s in U:
 x=pd.read_csv('../persistent/stock_data/'+s+'.csv'); x.date=pd.to_datetime(x.date); P[s]=x[x.date<=END].set_index('date').close.sort_index()
px=pd.DataFrame(P).sort_index(); r=px.pct_change()
# downside semideviation, lagged to ensure only completed information
neg=r.where(r<0,0.0); sig=-neg.rolling(20,min_periods=20).std().shift(1); fwd=px.shift(-1)/px-1

def calc(S,F,mask=None):
 a=[]; n=[]; dates=[]
 for d in S.index:
  if mask is not None and not mask.loc[d]: continue
