for name,x in [('recent180',ic.tail(180)),('recent360',ic.tail(360)),('2030',ic.loc['2030']),('recent60',ic.tail(60))]: print(name,len(x),'IC %.6f ICIR %.6f'%(x.ic.mean(),x.ic.mean()/x.ic.std() if len(x)>1 and x.ic.std() else np.nan))
for h in [1,5,10,20]:
 q=[]; f=px.shift(-h)/px-1
